// Розбір заявок «Admin | Leaver» (трекер 25): дата звільнення, ім'я (обидва порядки), кому передати диск.
// Вихід: action = 'process' або 'notify' (бракує даних; коментар пишеться один раз, пам'ять у static data).
const TERM_DATE_CF_ID = 30;   // «Termination date» (на тесті інший номер, тому шукаємо й за назвою)
const ENG_CF_ID = 11, UKR_CF_ID = 103, MANAGER_CF_ID = 25;

const state = $getWorkflowStaticData('global');
state.notified = state.notified || {};
const today = DateTime.now().setZone('Europe/Kyiv').toISODate();

let issues = [];
for (const it of $input.all()) {
  if (Array.isArray(it.json.issues)) issues.push(...it.json.issues);
  else if (it.json && it.json.id) issues.push(it.json);
}
const cf = (issue, id, name) => (issue.custom_fields || []).find(f => f.id === id || f.name === name);
const cfv = (issue, id, name) => { const f = cf(issue, id, name); return f && f.value ? String(f.value).trim() : ''; };

// Транслітерація КМУ-2010 (як імена записані в AD/Google).
const TR = { а:'a', б:'b', в:'v', г:'h', ґ:'g', д:'d', е:'e', є:'ie', ж:'zh', з:'z', и:'y', і:'i', ї:'i', й:'i', к:'k', л:'l',
  м:'m', н:'n', о:'o', п:'p', р:'r', с:'s', т:'t', у:'u', ф:'f', х:'kh', ц:'ts', ч:'ch', ш:'sh', щ:'shch', ь:'', ю:'iu', я:'ia',
  ы:'y', э:'e', ё:'io', ъ:'' };
const TR_START = { є:'ye', ї:'yi', й:'y', ю:'yu', я:'ya', ё:'yo' };
function translit(word) {
  const w = word.toLowerCase().replace(/[’'ʼ`]/g, '').replace(/зг/g, 'zgh');
  let out = '';
  for (let i = 0; i < w.length; i++) out += (i === 0 && TR_START[w[i]]) || (TR[w[i]] !== undefined ? TR[w[i]] : w[i]);
  return out.charAt(0).toUpperCase() + out.slice(1);
}
const isCyr = s => /[А-Яа-яЁёЄєІіЇїҐґ]/.test(s);
const isLat = s => /^[A-Za-z][A-Za-z'’ʼ-]*$/.test(s);

// Пари [ім'я, прізвище] в обох порядках: «Ivan Testovenko» і «Probenko Olha» пишуть по-різному.
function namePairs(raw) {
  const parts = String(raw || '').replace(/^(ФОП|ФЛП)\s+/i, '').split(/[\s/,]+/).filter(Boolean);
  if (parts.length < 2) return [];
  let a = parts[0], b = parts[1];
  if (isCyr(a) || isCyr(b)) { if (!isCyr(a) || !isCyr(b)) return []; a = translit(a); b = translit(b); }
  else if (!isLat(a) || !isLat(b)) return [];
  const pairs = [[a, b], [b, a]];
  // Латиниця з трьох-чотирьох слів («Adam Leopold Tester»): в AD і Google часто лише «перше + останнє».
  if (!isCyr(parts[0]) && parts.length >= 3 && parts.length <= 4 && parts.every(isLat)) {
    const f = parts[0], l = parts[parts.length - 1];
    pairs.unshift([f, l], [l, f]);
  }
  return pairs.filter((p, i, arr) => arr.findIndex(q => q[0] === p[0] && q[1] === p[1]) === i);
}

function parseDate(issue) {
  let d = cfv(issue, TERM_DATE_CF_ID, 'Termination date') || issue.due_date || '';
  d = String(d).trim();
  if (!d) return { reason: 'no_date' };
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d) || !DateTime.fromISO(d).isValid) return { reason: 'bad_date', value: d };
  return { date: d };
}

// Кому передати диск. mode: email | name | manager | none
const NO_TRANSFER = /(не\s*(потрібно|треба|переадресов\p{L}*|передава\p{L}*)|видалити|немає|^ні$|^-$)/iu;
function parseDrive(description, manager) {
  const d = description || '';
  if (/(дані|диск)[^\r\n]{0,40}передавати\s+не\s+потрібно/i.test(d)) return { mode: 'none', text: 'передавати не потрібно' };
  const m = d.match(/Переадресація\s+диску\s*[:\-–—]\s*([^\r\n]*)/i)
         || d.match(/Дані\s+(?:пошти\s+(?:та|і|й)\s+)?диску\s+передати\s*[:\-–—]?\s*([^\r\n]*)/i);
  if (m) {
    const v = m[1].trim();
    const email = (v.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/) || [])[0];
    if (email) return { mode: 'email', email: email.toLowerCase(), text: v };
    if (!v || NO_TRANSFER.test(v)) return { mode: 'none', text: v || 'не вказано' };
    const pairs = namePairs(v.replace(/[-–—].*$/, '').trim());
    return pairs.length ? { mode: 'name', name: v, pairs, text: v } : { mode: 'unknown', text: v };
  }
  const mp = namePairs(manager);
  return mp.length ? { mode: 'manager', name: manager, pairs: mp, text: `не вказано, менеджер: ${manager}` }
                   : { mode: 'unknown', text: 'не вказано, менеджера в заявці немає' };
}

const NOTES = {
  no_date: () => ['• Поле «Termination date»: порожнє.\n• Due date: порожня.',
    'не вказано дату звільнення, тому невідомо, коли закривати доступи.',
    ['заповніть «Termination date» (РРРР-ММ-ДД); у день звільнення або пізніше автоматизація обробить заявку сама.']],
  bad_date: v => [`• Дата звільнення в заявці: «${v}».`, `дату «${v}» не вдалося розпізнати (очікується РРРР-ММ-ДД).`,
    ['виправте дату в полі «Termination date», і автоматизація обробить заявку сама.']],
  no_name: v => [`• «Contractor (ENG)»: «${v.eng || ''}».\n• «Contractor (UKR)»: «${v.ukr || ''}».`,
    'не вдалося визначити ім\'я та прізвище працівника, тому шукати його в AD, Google і M365 немає за чим.',
    ['заповніть «Contractor (ENG)» у форматі «Ім\'я Прізвище» латиницею.']],
};
const fmt = ([checked, result, next]) =>
  `⚠ Автоматичний offboarding не виконано.\n\nЩо перевірено:\n${checked}\n\nРезультат: ${result}\n\n` +
  `Що робити далі:\n${next.map((s, i) => `${i + 1}. ${s.charAt(0).toUpperCase()}${s.slice(1)}`).join('\n')}\n\n` +
  'Заявку залишено відкритою. Нічого в AD, Google і M365 не змінено. Автоматизація перевіряє заявку щодня о 18:00; про ту саму проблему повторно не пише.';

const results = [];
const openIds = new Set();
for (const issue of issues) {
  if (!issue || !issue.tracker || issue.tracker.id !== 25) continue;
  const id = issue.id;
  openIds.add(String(id));
  const D = parseDate(issue);
  if (D.date && D.date > today) continue;  // ще не звільнився

  const eng = cfv(issue, ENG_CF_ID, 'Contractor (ENG)');
  const ukr = cfv(issue, UKR_CF_ID, 'Contractor (UKR)');
  const pairs = namePairs(eng).length ? namePairs(eng) : namePairs(ukr);
  const problem = D.reason ? D : (!pairs.length ? { reason: 'no_name', value: { eng, ukr } } : null);
  if (problem) {
    const key = 'input:' + problem.reason + ':' + JSON.stringify(problem.value || '');
    if (state.notified[id] === key) continue;
    state.notified[id] = key;
    results.push({ json: { action: 'notify', id, reason: problem.reason, note: fmt(NOTES[problem.reason](problem.value)) } });
    continue;
  }
  if (String(state.notified[id] || '').startsWith('input:')) delete state.notified[id];
  const manager = cfv(issue, MANAGER_CF_ID, 'Manager');
  // Шаблони логінів в AD (запасний пошук, якщо в акаунта не заповнені ім'я/прізвище):
// ім'я.прізвище, і.прізвище, ms.і.прізвище, ms.ім'я.прізвище (ms. у старих акаунтів).
const loginVariants = (g, s) => {
  const G = g.toLowerCase().replace(/[^a-z-]/g, ''), S = s.toLowerCase().replace(/[^a-z-]/g, '');
  if (!G || !S) return [];
  return [`${G}.${S}`, `${G[0]}.${S}`, `ms.${G[0]}.${S}`, `ms.${G}.${S}`];
};
  // Значення для шаблону фільтра в LDAP-ноді: фіксовані слоти, зайві = NONE (нічого не знаходить).
  // Нода сама екранує підставлені значення, тому тут лише прибираємо службові символи.
  const NONE = '__none__';
  const ldapClean = s => String(s).replace(/[\\*()\0]/g, '');
  const pad = (values, n) => {
    if (values.length > n) throw new Error('Забагато значень для фільтра AD, ' + values.length + ' з ' + n);
    return values.concat(Array(n - values.length).fill(NONE));
  };
  results.push({ json: {
    action: 'process', id, subject: issue.subject || '', leaver_date: D.date,
    person: eng || ukr, pairs, drive: parseDrive(issue.description, manager === '-' ? '' : manager),
    login_variants: [...new Set(pairs.flatMap(([g, s]) => loginVariants(g, s)))],
    ldap_gn: pad(pairs.map(p => ldapClean(p[0])), 4),
    ldap_sn: pad(pairs.map(p => ldapClean(p[1])), 4),
    ldap_sam: pad([...new Set(pairs.flatMap(([g, s]) => loginVariants(g, s)).map(ldapClean).filter(Boolean))], 16),
  } });
}
for (const k of Object.keys(state.notified)) if (!openIds.has(k)) delete state.notified[k];
return results;

// Пошук в AD за ім'ям і прізвищем (обидва порядки) по всьому домену. Блокуємо лише при єдиному збігу в OU=AllUsers.
// ad.status: disable | already_done | not_found | multiple | outside_scope | fired_but_enabled
const SCOPE = ',OU=AllUsers,OU=COMPANY,DC=example,DC=com';
const FIRED_OU = 'OU=Уволенные,DC=example,DC=com';
const ctx = $('Loop Over Tickets').first().json;
const one = v => Array.isArray(v) ? v[0] : v;
const endsCI = (s, t) => s.toLowerCase().endsWith(t.toLowerCase());
const low = v => String(one(v) || '').toLowerCase();
const all = $input.all().map(i => i.json).filter(j => j && j.dn);
// Спершу збіг імені й прізвища; якщо нема, запасний шлях: логін за шаблоном, ім'я/прізвище порожні або збігаються.
const byName = all.filter(j => ctx.pairs.some(([g, s]) => low(j.givenName) === g.toLowerCase() && low(j.sn) === s.toLowerCase()));
const byLogin = all.filter(j => (ctx.login_variants || []).includes(low(j.sAMAccountName)) &&
  ctx.pairs.some(([g, s]) => (!low(j.givenName) || low(j.givenName) === g.toLowerCase()) && (!low(j.sn) || low(j.sn) === s.toLowerCase())));
let found = byName.length ? byName : byLogin;
// Кілька акаунтів з таким іменем: уже заблоковані дублікати ігноруємо, якщо активний рівно один.
let ignoredDisabled = [];
const activeOnly = found.filter(j => !((parseInt(one(j.userAccountControl), 10) || 0) & 2));
if (found.length > 1 && activeOnly.length === 1) { ignoredDisabled = found.filter(j => j !== activeOnly[0]); found = activeOnly; }
const where = j => {
  const dn = String(j.dn), uac = parseInt(one(j.userAccountControl), 10) || 0;
  const ou = endsCI(dn, ',' + FIRED_OU) ? 'Уволенные' : (dn.match(/,OU=([^,]+)/) || [])[1] || '?';
  return `${one(j.sAMAccountName)} (${ou}, ${(uac & 2) ? 'заблокований' : 'активний'})`;
};
const ad = { status: '', dn: '', target_dn: '', new_uac: '', login: '', candidates: found.map(where).join('; '),
  by_login_pattern: !byName.length && byLogin.length === 1,
  ignored_disabled: ignoredDisabled.map(where).join('; ') };
if (found.length === 0) ad.status = 'not_found';
else if (found.length > 1) ad.status = 'multiple';
else {
  const j = found[0], dn = String(j.dn), uac = parseInt(one(j.userAccountControl), 10) || 0;
  ad.dn = dn; ad.login = String(one(j.sAMAccountName) || '');
  if (endsCI(dn, ',' + FIRED_OU)) ad.status = (uac & 2) ? 'already_done' : 'fired_but_enabled';
  else if (endsCI(dn, SCOPE)) {
    ad.status = 'disable';
    ad.new_uac = String(uac | 2);  // лише ACCOUNTDISABLE, інші прапорці не чіпаємо
    ad.target_dn = `${dn.match(/^((?:\\.|[^,\\])+),/)[1]},${FIRED_OU}`;
  } else ad.status = 'outside_scope';
}
return [{ json: { ...ctx, ad }, pairedItem: { item: 0 } }];

// Результат кроку AD (блокування і перенесення, або пропуск) + запити пошуку людини в Google.
// По одному запиту на кожен порядок імені: Google не вміє OR у query.
const ctx = $('Code: Decide AD Action').first().json;
const r = $input.first().json;
const text = e => String((e && (e.message || e.description)) || e || 'невідома помилка');
const ad = { ...ctx.ad };
if (ad.status === 'disable') {
  const disableErr = $('[AD] Disable Account').first().json.error;   // блокування не вдалося: перенесення не запускалось
  const err = disableErr || r.error;                                  // інакше помилка могла бути лише в перенесенні
  if (err) { ad.result = 'error'; ad.error = `${disableErr ? 'блокування' : 'перенесення в «Уволенные»'}: ${text(err)}`; }
  else ad.result = 'disabled';
} else ad.result = ad.status;
const merged = { ...ctx, ad };
const q = s => `'${String(s).replace(/'/g, "\\'")}'`;
return ctx.pairs.map(([g, s]) => ({ json: { ...merged,
  url: 'https://admin.googleapis.com/admin/directory/v1/users?customer=my_customer&maxResults=10&query=' +
       encodeURIComponent(`givenName:${q(g)} familyName:${q(s)}`) }, pairedItem: { item: 0 } }));

// Що робити з акаунтом Google: google.status = suspend | already_suspended | not_found | multiple | error
const ctx = $('Code: Prepare Google Search').first().json;
const res = $input.all().map(i => i.json);
const err = res.find(r => Number(r.statusCode) !== 200);
const users = {};
for (const r of res) for (const u of ((r.body && r.body.users) || [])) users[u.id] = u;
const list = Object.values(users);
const google = { status: '', id: '', email: '', candidates: list.map(u => `${u.primaryEmail}${u.suspended ? ' (призупинений)' : ''}`).join('; ') };
if (err && !list.length) { google.status = 'error'; google.error = `${err.statusCode}: ${(err.body && err.body.error && err.body.error.message) || err.statusMessage || 'немає відповіді'}`; }
else if (list.length === 0) google.status = 'not_found';
else if (list.length > 1) google.status = 'multiple';
else {
  const u = list[0];
  google.id = u.id; google.email = u.primaryEmail;
  google.status = u.suspended ? 'already_suspended' : 'suspend';
}
return [{ json: { ...ctx, google }, pairedItem: { item: 0 } }];

// Результат кроку Google (призупинення або пропуск), стан заявки з історії коментарів і запит пошуку отримувача диска.
// Стан: техніка, підтвердження передачі диска («так» після питання бота), попередні звіти бота.
// Нотатки бота впізнаємо за «Автоматичний offboarding» (старий флоу писав «Автоматичний Offboarding»).
const ctx = $('Code: Decide Google Action').first().json;
const r = $input.first().json;
const google = { ...ctx.google };
if (google.status === 'suspend') {
  const code = Number(r.statusCode);
  if (code >= 200 && code < 300 && r.body && r.body.suspended === true) google.result = 'suspended';
  else { google.result = 'error'; google.error = `${code || 'немає відповіді'}: ${(r.body && r.body.error && r.body.error.message) || (r.error && r.error.message) || 'акаунт не призупинено'}`; }
} else google.result = google.status;

const t = $('[Redmine] Get Ticket History').first().json;
const issue = t.issue || t;
const journals = (issue.journals || []).filter(j => j && j.notes);
const isBot = n => /Автоматичний\s+offboarding/i.test(n);

// Техніка: вирішує останній людський коментар про техніку (старий бот брехав «Заборгованості немає», його не рахуємо).
// \p{L} з прапорцем u: без нього \w і \b у JS не бачать кирилицю.
const EQ_OK = /забор\p{L}*\s+по\s+техн\p{L}*\s+нема|техн\p{L}*\s+(повернуто|повернув|повернула|здано|здав|здала)|нічого\s+не\s+числиться/iu;
const EQ_DEBT = /(закріплен\p{L}*|числиться|не\s+поверну\p{L}*|не\s+здан\p{L}*)[^\r\n]{0,40}(ноут|техн|монітор|комп|пк|телефон|гарнітур|інв)/iu;
let equipment = 'unknown', equipment_note = '';
for (const j of journals) {
  if (isBot(j.notes)) continue;
  if (EQ_DEBT.test(j.notes)) { equipment = 'debt'; equipment_note = j.notes.trim(); }
  else if (EQ_OK.test(j.notes)) { equipment = 'ok'; equipment_note = j.notes.trim(); }
}

// Передача диска: питання бота «Передати диск ... (email)?» і пізніша людська відповідь «так».
let asked_email = '', confirmed_email = '', drive_done_before = false;
for (const j of journals) {
  if (isBot(j.notes)) {
    const q = j.notes.match(/Передати\s+диск[^\r\n]*?\(([^)\s]+@[^)\s]+)\)\?/i);
    if (q) { asked_email = q[1].toLowerCase(); confirmed_email = ''; }
    if (/•\s*Диск:\s*перенесення\s+запущено/i.test(j.notes)) drive_done_before = true;  // рядок зі звіту final_report.js
    if (/Google\s+Диск[\s\S]{0,400}?Успішно\s+ініційовано/i.test(j.notes)) drive_done_before = true;  // звіт старого флоу
  } else if (asked_email && /^\s*(так|да|yes|ок|ok|\+|підтверджую)(?=$|[\s.,!)])/iu.test(j.notes)) {
    confirmed_email = asked_email;
  }
}

const prior_report = journals.some(j => isBot(j.notes) && /(успішно\s+завершено|Звіт\s+про\s+закриття\s+доступів)/i.test(j.notes));


const merged = { ...ctx, google, equipment, equipment_note, asked_email, confirmed_email, drive_done_before, prior_report };

// Кого шукати в Google як отримувача диска. Без запиту, якщо передавати не треба або акаунта працівника немає.
const d = ctx.drive || {};
const base = 'https://admin.googleapis.com/admin/directory/v1/users';
const q = s => `'${String(s).replace(/'/g, "\\'")}'`;
const leaverOk = ['suspended', 'already_suspended'].includes(google.result);
let urls = [];
if (leaverOk && !drive_done_before) {
  if (d.mode === 'email') urls = [`${base}/${encodeURIComponent(d.email)}`];
  else if (['name', 'manager'].includes(d.mode)) {
    urls = confirmed_email ? [`${base}/${encodeURIComponent(confirmed_email)}`]
      : d.pairs.map(([g, s]) => `${base}?customer=my_customer&maxResults=10&query=` + encodeURIComponent(`givenName:${q(g)} familyName:${q(s)}`));
  }
}
return (urls.length ? urls : ['']).map(url => ({ json: { ...merged, url }, pairedItem: { item: 0 } }));

// Що робити з диском: drive.action = transfer | ask | none | skip
const ctx = $('Code: Prepare Drive Transfer').first().json;
const d = { ...(ctx.drive || {}) };
const res = $input.all().map(i => i.json).filter(r => r.statusCode !== undefined);
const users = {};
for (const r of res) {
  if (Number(r.statusCode) !== 200 || !r.body) continue;
  for (const u of (r.body.users || (r.body.primaryEmail ? [r.body] : []))) if (!u.suspended) users[u.id] = u;
}
const list = Object.values(users);
const leaverOk = ['suspended', 'already_suspended'].includes(ctx.google.result);
d.candidates = list.map(u => `${(u.name && u.name.fullName) || ''} (${u.primaryEmail})`).join('; ');

if (ctx.drive_done_before) { d.action = 'skip'; d.status = 'done_before'; }
else if (d.mode === 'none') { d.action = 'none'; d.status = 'not_needed'; }
else if (d.mode === 'unknown') { d.action = 'none'; d.status = 'unknown_target'; }
else if (!leaverOk) { d.action = 'none'; d.status = 'no_leaver_account'; }
else if (list.length === 0) { d.action = 'none'; d.status = d.mode === 'email' ? 'recipient_not_found' : 'recipient_name_not_found'; }
else if (list.length > 1) { d.action = 'none'; d.status = 'recipient_multiple'; }
else {
  const u = list[0];
  d.recipient_id = u.id; d.recipient_email = u.primaryEmail.toLowerCase();
  d.recipient_name = (u.name && u.name.fullName) || u.primaryEmail;
  const confirmed = d.mode === 'email' || (ctx.confirmed_email && ctx.confirmed_email === d.recipient_email);
  if (confirmed) { d.action = 'transfer'; d.status = 'transfer'; }
  else { d.action = 'ask'; d.status = 'ask'; }
}
return [{ json: { ...ctx, drive: d }, pairedItem: { item: 0 } }];

// Результат передачі диска (запуск або пропуск) + запит пошуку в Microsoft Graph:
// члени тенанта (не гості #EXT#) з таким ім'ям і прізвищем, обидва порядки.
const ctx = $('Code: Decide Drive Action').first().json;
const r = $input.first().json;
const drive = { ...ctx.drive };
if (drive.action === 'transfer') {
  const code = Number(r.statusCode);
  if (code >= 200 && code < 300) { drive.result = 'transferred'; drive.transfer_status = (r.body && r.body.overallTransferStatusCode) || ''; }
  else { drive.result = 'error'; drive.error = `${code || 'немає відповіді'}: ${(r.body && r.body.error && r.body.error.message) || (r.error && r.error.message) || 'перенесення не запущено'}`; }
} else drive.result = drive.status;
const e = s => String(s).replace(/'/g, "''");
const filter = ctx.pairs.map(([g, s]) => `(givenName eq '${e(g)}' and surname eq '${e(s)}')`).join(' or ');
return [{ json: { ...ctx, drive,
  url: 'https://graph.microsoft.com/v1.0/users?$select=id,userPrincipalName,mail,givenName,surname,accountEnabled,userType&$top=10&$filter=' + encodeURIComponent(filter) },
  pairedItem: { item: 0 } }];

// Що робити з акаунтом M365: m365.status = delete | not_found | multiple | error
const ctx = $('Code: Prepare M365 Search').first().json;
const r = $input.first().json;
const m365 = { status: '', id: '', upn: '' };
if (Number(r.statusCode) !== 200) {
  m365.status = 'error';
  m365.error = `${r.statusCode || 'немає відповіді'}: ${(r.body && r.body.error && r.body.error.message) || 'пошук не вдався'}`;
} else {
  const list = ((r.body && r.body.value) || []).filter(u => u.userType !== 'Guest' && !String(u.userPrincipalName).includes('#EXT#'));
  m365.candidates = list.map(u => u.userPrincipalName).join('; ');
  if (list.length === 0) m365.status = 'not_found';
  else if (list.length > 1) m365.status = 'multiple';
  else { m365.status = 'delete'; m365.id = list[0].id; m365.upn = list[0].userPrincipalName; }
}
return [{ json: { ...ctx, m365 }, pairedItem: { item: 0 } }];

// Підсумок по заявці: звіт по кожній системі, техніка, диск, звірка логінів; рішення, чи закривати.
// Закриваємо лише коли: немає проблем, диск вирішено, IT підтвердив «Заборгованості по техніці немає».
// Якщо доступи закрито раніше і зараз нічого не змінено: короткий коментар. Той самий коментар двічі не пишемо.
const c0 = $('Code: Decide M365 Action').first().json;
const r = $input.first().json;
const m365 = { ...c0.m365 };
if (m365.status === 'delete') {
  const code = Number(r.statusCode);
  if (code >= 200 && code < 300) m365.result = 'deleted';
  else { m365.result = 'error'; m365.error = `${code || 'немає відповіді'}: ${(r.body && r.body.error && r.body.error.message) || 'не видалено'}`; }
} else m365.result = m365.status;
const c = { ...c0, m365 };
const state = $getWorkflowStaticData('global');
state.notified = state.notified || {};
const who = c.pairs[0].join(' ');
const problems = [], pending = [];
const ign = c.ad.ignored_disabled ? ` (інші акаунти з таким іменем уже заблоковані й пропущені: ${c.ad.ignored_disabled})` : '';
const pat = (c.ad.by_login_pattern ? ' (ім’я/прізвище в AD не заповнені, знайдено за шаблоном логіна)' : '') + ign;

const AD = {
  disabled: () => `Акаунт ${c.ad.login} заблоковано та переміщено в OU «Уволенные».${pat}`,
  already_done: () => `Акаунт ${c.ad.login} уже був заблокований (OU «Уволенные»).${pat}`,
  not_found: () => `Акаунт за ім'ям «${who}» не знайдено (можливо, вже видалено).`,
  multiple: () => { problems.push('AD: кілька акаунтів'); return `Знайдено кілька акаунтів: ${c.ad.candidates}. Нічого не змінено, визначте потрібний вручну.`; },
  outside_scope: () => { problems.push('AD: акаунт поза OU=AllUsers'); return `Акаунт знайдено поза OU=AllUsers (${c.ad.dn}). Нічого не змінено, потрібна ручна перевірка.`; },
  fired_but_enabled: () => { problems.push('AD: у «Уволенные», але активний'); return `Акаунт ${c.ad.login} уже в OU «Уволенные», але не заблокований. Заблокуйте вручну.`; },
  error: () => { problems.push('AD: помилка'); return `НЕ виконано (${c.ad.error}). Перевірте права сервісного облікового запису n8n в AD.`; },
};
const GOOGLE = {
  suspended: () => `Акаунт ${c.google.email} призупинено (Suspended).`,
  already_suspended: () => `Акаунт ${c.google.email} уже був призупинений.`,
  not_found: () => { problems.push('Google: акаунт не знайдено'); return `Акаунт за ім'ям «${who}» не знайдено. Якщо ім'я в Google записане інакше, призупиніть акаунт вручну; якщо акаунт уже видалено, закрийте заявку вручну.`; },
  multiple: () => { problems.push('Google: кілька акаунтів'); return `Знайдено кілька акаунтів: ${c.google.candidates}. Нічого не змінено, визначте потрібний вручну.`; },
  error: () => { problems.push('Google: помилка'); return `НЕ виконано (${c.google.error}).`; },
};
const d = c.drive;
const DRIVE = {
  transferred: () => `• Диск: перенесення запущено (кому: ${d.recipient_name}, ${d.recipient_email}).`,
  done_before: () => '• Диск: перенесення було запущено раніше.',
  not_needed: () => `• Диск: передавати не потрібно (у заявці: «${d.text}»).`,
  ask: () => { pending.push('підтвердження передачі диска');
    return `• Передати диск: ${d.recipient_name} (${d.recipient_email})?\n  У заявці: «${d.text}». Якщо так, дайте відповідь коментарем «так», і автоматизація передасть диск під час наступного запуску.`; },
  recipient_not_found: () => { pending.push('отримувач диска');
    return `• Диск: отримувача ${d.email} не знайдено в Google (або він призупинений). Вкажіть актуальний e-mail у рядку «Переадресація диску: ...».`; },
  recipient_name_not_found: () => { pending.push('отримувач диска');
    return `• Диск: кому передати, вказано як «${d.text}», але в Google такого працівника не знайдено. Вкажіть e-mail у рядку «Переадресація диску: ...».`; },
  recipient_multiple: () => { pending.push('отримувач диска');
    return `• Диск: за «${d.text}» знайдено кількох: ${d.candidates}. Вкажіть e-mail у рядку «Переадресація диску: ...».`; },
  unknown_target: () => { pending.push('отримувач диска');
    return `• Диск: не зрозуміло, кому передати (у заявці: «${d.text}»). Вкажіть e-mail у рядку «Переадресація диску: ...» або напишіть «не потрібно».`; },
  no_leaver_account: () => '• Диск: не виконувалось (акаунт Google працівника не знайдено).',
  error: () => { problems.push('Google Диск: помилка'); return `• Диск: перенесення НЕ запущено (${d.error}).`; },
};
const M365 = {
  deleted: () => `Акаунт ${c.m365.upn} видалено.`,
  not_found: () => `Акаунта за ім'ям «${who}» немає, видаляти нічого.`,
  multiple: () => { problems.push('M365: кілька акаунтів'); return `Знайдено кілька акаунтів: ${c.m365.candidates}. Нічого не видалено, визначте потрібний вручну.`; },
  error: () => { problems.push('M365: помилка'); return `НЕ виконано (${c.m365.error}).`; },
};
let eq;
if (c.equipment === 'ok') eq = 'IT підтвердив: заборгованості по техніці немає.';
else if (c.equipment === 'debt') { pending.push('повернення техніки'); eq = `За працівником числиться техніка (коментар у заявці: «${c.equipment_note.slice(0, 200)}»).`; }
else { pending.push('підтвердження IT щодо техніки'); eq = 'Підтвердження IT щодо техніки ще немає. Коли техніку перевірено, напишіть коментар «Заборгованості по техніці немає».'; }

const lines = {
  ad: AD[c.ad.result](), google: GOOGLE[c.google.result](), drive: DRIVE[d.result](), m365: M365[c.m365.result](),
};
// Звірка логінів між системами: різні логіни можуть означати, що знайдено різних людей.
const logins = [c.ad.login, (c.google.email || '').split('@')[0], (c.m365.upn || '').split('@')[0]].filter(Boolean).map(s => s.toLowerCase());
const warn = new Set(logins).size > 1 ? `\n⚠ Логіни в системах відрізняються (${[...new Set(logins)].join(', ')}). Перевірте, що це одна й та сама людина.\n` : '';

const close = !problems.length && !pending.length;
const acted = c.ad.result === 'disabled' || c.google.result === 'suspended' || d.result === 'transferred' || c.m365.result === 'deleted';
const tail = 'Автоматизація перевіряє заявку щодня о 18:00; той самий коментар повторно не пише.';

let note;
if (c.prior_report && !acted && !problems.length) {
  note = close
    ? 'Автоматичний offboarding: доступи закрито раніше (див. попередній звіт). IT підтвердив, що заборгованості по техніці немає. Заявку закрито.'
    : `Автоматичний offboarding: доступи закрито раніше (див. попередній звіт), повторно нічого не виконувалось.\nЗаявку залишено відкритою, бо очікується: ${pending.join(', ')}.\n${eq}\n${['ask', 'recipient_not_found', 'recipient_name_not_found', 'recipient_multiple', 'unknown_target'].includes(d.result) ? lines.drive + '\n' : ''}\n${tail}`;
} else {
  const head = close ? 'Автоматичний offboarding: доступи закрито, заявку закрито.'
    : problems.length ? '⚠ Автоматичний offboarding виконано частково, потрібна ручна дія.'
    : 'Автоматичний offboarding: доступи закрито, заявку залишено відкритою.';
  note = `${head}\n\nЗвіт про закриття доступів (працівник: ${c.person}):\n` +
    `1. Active Directory: ${lines.ad}\n2. Google Workspace: ${lines.google}\n${lines.drive}\n3. Microsoft 365: ${lines.m365}\n4. Техніка: ${eq}\n` + warn +
    (close ? '\nЗапис додано до архівного реєстру Google Sheets.' :
      `\nЩо залишилось: ${[...problems, ...pending].join('; ')}.\nЗаявку залишено відкритою. ${tail}`);
}

const key = (close ? 'close|' : 'open|') + note.replace(/\d{4}-\d{2}-\d{2}/g, '');
const notify = close || state.notified[c.id] !== key;
if (close) delete state.notified[c.id]; else state.notified[c.id] = key;

// В архів пишемо лише при першому закритті (не після переоткриття заявки).
return [{ json: { id: c.id, close, archive: close && !c.prior_report, notify, note, leaver_date: c.leaver_date,
  login: c.ad.login || c.google.email || c.person, google_email: c.google.email || '' }, pairedItem: { item: 0 } }];
